#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

typedef unsigned int u32;
typedef unsigned long long u64;

static unsigned s_nFailures = 0;

static void Expect (bool bCondition, const char *pWhat)
{
	if (!bCondition)
	{
		printf ("  FALLO  %s\n", pWhat);
		s_nFailures++;
	}
	else
	{
		printf ("  ok     %s\n", pWhat);
	}
}

static u32 Rgb (unsigned nR, unsigned nG, unsigned nB)
{
	return (nR << 16) | (nG << 8) | nB;
}

static void ResampleRowBox (const u32 *pSrcRow, unsigned nSrcW,
			    u32 *pDstRow, unsigned nDstW)
{
	// 16 bits of fractional position.  nStep is the distance between two
	// destination pixels in source coordinates.
	//
	// The accumulators below are 64-bit on purpose.  With 32 bits they are
	// safe only while a destination pixel spans at most two source pixels
	// (255 x 2 x 65536 is just under 2^32), which is true of every scale this
	// port actually uses - and false the moment something reduces by more
	// than 2, where they wrap and produce colours with no relation to the
	// picture.  The generator's test drives the function at 640 -> 1 to keep
	// that case honest; 64-bit registers cost nothing on AArch64 and remove
	// the cliff instead of documenting where it is.
	constexpr unsigned FracBits = 16;
	constexpr unsigned FracOne = 1u << FracBits;

	unsigned nPos = 0;
	const unsigned nStep = (nSrcW << FracBits) / nDstW;

	// One reciprocal instead of a divide per pixel.
	//
	// Three 32-bit divides per output pixel is ~50 cycles each on a Cortex-A72
	// (there is no hardware integer divide), and at 1392x1044 that alone is
	// 200 ms per frame - more than the frame budget of a 70 Hz mode.  So the
	// reciprocal of the span is computed once per row and each pixel costs a
	// multiply and a shift.
	//
	// Two details that are not cosmetic, both found by the generator's test:
	//
	//   * the reciprocal is floored, so a multiply-shift alone always rounds
	//     *down*: a flat white row came out 254.  Half an ulp is added before
	//     the shift, which makes it round to nearest and gives 255 back.
	//   * 32 bits of reciprocal is not enough when the span is large: at
	//     640 -> 1 the reciprocal is 102.4 and the truncation alone loses a
	//     level off every channel.  48 bits costs nothing (the product still
	//     fits in 64: the accumulator is at most 255 x nStep, and nStep x
	//     2^48/nStep is 255 x 2^48 = 7.2e16) and the error becomes invisible
	//     even at the extreme.
	//   * nWeightSum is nStep for every pixel except possibly the last, where
	//     the clamp to nSrcW can cut the span short.  Those pixels take the
	//     true divide, which is at most one per row.
	constexpr unsigned InvBits = 48;
	constexpr u64 InvOne = 1ull << InvBits;
	constexpr u64 nHalfUlp = InvOne / 2;

	const u64 nInvSpan = InvOne / nStep;

	for (unsigned nX = 0; nX < nDstW; nX++)
	{
		const unsigned nEnd = nPos + nStep;

		const unsigned nFirst = nPos >> FracBits;
		unsigned nLast = (nEnd - 1) >> FracBits;
		if (nLast >= nSrcW)
		{
			nLast = nSrcW - 1;
		}

		unsigned nWeightSum = 0;
		u64 nR = 0, nG = 0, nB = 0;

		for (unsigned nI = nFirst; nI <= nLast; nI++)
		{
			const unsigned nPixStart = nI << FracBits;
			const unsigned nPixEnd = nPixStart + FracOne;

			const unsigned nFrom = nPos > nPixStart ? nPos : nPixStart;
			const unsigned nTo = nEnd < nPixEnd ? nEnd : nPixEnd;
			if (nTo <= nFrom)
			{
				continue;
			}

			const unsigned nWeight = nTo - nFrom;
			const u32 nPixel = pSrcRow[nI];

			nR += static_cast<u64> ((nPixel >> 16) & 0xFF) * nWeight;
			nG += static_cast<u64> ((nPixel >> 8) & 0xFF) * nWeight;
			nB += static_cast<u64> (nPixel & 0xFF) * nWeight;
			nWeightSum += nWeight;
		}

		if (nWeightSum == 0)
		{
			nWeightSum = 1;		// unreachable; keeps the divide defined
		}

		// nWeightSum == nStep for every pixel except the last, where the
		// clamp to nSrcW can cut it short; the reciprocal is therefore
		// exact enough everywhere and the one true divide stays for the
		// last pixel only when it differs.
		unsigned nR8, nG8, nB8;
		if (nWeightSum == nStep)
		{
			nR8 = static_cast<unsigned> ((nR * nInvSpan + nHalfUlp) >> InvBits);
			nG8 = static_cast<unsigned> ((nG * nInvSpan + nHalfUlp) >> InvBits);
			nB8 = static_cast<unsigned> ((nB * nInvSpan + nHalfUlp) >> InvBits);
		}
		else
		{
			nR8 = static_cast<unsigned> ((nR + nWeightSum / 2) / nWeightSum);
			nG8 = static_cast<unsigned> ((nG + nWeightSum / 2) / nWeightSum);
			nB8 = static_cast<unsigned> ((nB + nWeightSum / 2) / nWeightSum);
		}

		pDstRow[nX] = (nR8 << 16) | (nG8 << 8) | nB8;

		nPos = nEnd;
	}
}

// ---------------------------------------------------------------------------

static void TestFlat (void)
{
	printf ("color plano: se conserva exacto\n");

	const unsigned nScales[][2] =
	{
		{ 320, 320 },		// 1:1, the identity case
		{ 320, 296 },		// a fraction under 1, as 640x480 -> 592x444
		{ 320, 232 },		// ~0.72, as 1280x720 -> 912x684
		{ 256, 200 },		// ~0.78
		{ 720, 528 },		// ~0.73
		{ 640, 466 },
		{ 640, 1 },		// pathological: all of the row into one pixel
		{ 8, 300 },		// upscale: more output than input
	};

	const u32 nColours[] = { Rgb (0, 0, 0), Rgb (255, 255, 255),
				 Rgb (12, 200, 77), Rgb (1, 2, 3), Rgb (128, 128, 128) };

	for (const auto& Scale : nScales)
	{
		const unsigned nSrcW = Scale[0];
		const unsigned nDstW = Scale[1];

		std::vector<u32> Src (nSrcW), Dst (nDstW + 4, 0xDEADBEEF);

		for (u32 nColour : nColours)
		{
			for (unsigned i = 0; i < nSrcW; i++)
			{
				Src[i] = nColour;
			}

			ResampleRowBox (Src.data (), nSrcW, Dst.data (), nDstW);

			bool bAllSame = true;
			for (unsigned i = 0; i < nDstW; i++)
			{
				if (Dst[i] != nColour)
				{
					bAllSame = false;
				}
			}

			char Msg[160];
			snprintf (Msg, sizeof Msg,
				  "%u -> %u, colour %06X survives every output pixel",
				  nSrcW, nDstW, nColour);
			Expect (bAllSame, Msg);
		}

		// Nothing outside nDstW may be written: the caller's buffer is
		// exactly s_nDstWidth, and a filter that writes one past it is a
		// heap overflow that only shows on the board.
		char Msg[160];
		snprintf (Msg, sizeof Msg, "%u -> %u, writes nothing past the end",
			  nSrcW, nDstW);
		Expect (Dst[nDstW] == 0xDEADBEEF && Dst[nDstW + 1] == 0xDEADBEEF, Msg);
	}
}

static void TestRamp (void)
{
	printf ("rampa: extremos y monotonia\n");

	const unsigned nScales[][2] = { { 320, 232 }, { 640, 466 }, { 320, 296 } };

	for (const auto& Scale : nScales)
	{
		const unsigned nSrcW = Scale[0];
		const unsigned nDstW = Scale[1];

		std::vector<u32> Src (nSrcW), Dst (nDstW);

		// Black to white across the row, in the red channel only.
		for (unsigned i = 0; i < nSrcW; i++)
		{
			Src[i] = Rgb (i * 255 / (nSrcW - 1), 0, 0);
		}

		ResampleRowBox (Src.data (), nSrcW, Dst.data (), nDstW);

		const unsigned nFirst = (Dst[0] >> 16) & 0xFF;
		const unsigned nLast = (Dst[nDstW - 1] >> 16) & 0xFF;

		char Msg[160];
		snprintf (Msg, sizeof Msg, "%u -> %u, left end stays black (%u)",
			  nSrcW, nDstW, nFirst);
		Expect (nFirst == 0, Msg);

		snprintf (Msg, sizeof Msg, "%u -> %u, right end stays white (%u)",
			  nSrcW, nDstW, nLast);
		Expect (nLast == 255, Msg);

		// Monotonic: a box filter of a ramp cannot go backwards.  This is
		// the test for an index that repeats the wrong pixel - a clamped
		// nLast or an nPos that does not advance shows up here first.
		bool bMonotonic = true;
		for (unsigned i = 1; i < nDstW; i++)
		{
			if (((Dst[i] >> 16) & 0xFF) < ((Dst[i - 1] >> 16) & 0xFF))
			{
				bMonotonic = false;
			}
		}

		snprintf (Msg, sizeof Msg, "%u -> %u, never goes backwards", nSrcW, nDstW);
		Expect (bMonotonic, Msg);

		// And it must actually be smooth: no step larger than one step of
		// the source ramp (plus rounding).  A nearest-neighbour scaler
		// fails this, and that is the point of the whole change.
		unsigned nMaxStep = 0;
		for (unsigned i = 1; i < nDstW; i++)
		{
			const unsigned nStep =
				((Dst[i] >> 16) & 0xFF) - ((Dst[i - 1] >> 16) & 0xFF);
			if (nStep > nMaxStep)
			{
				nMaxStep = nStep;
			}
		}

		// The source ramp rises by 1 every ~1.4 pixels, so a smooth
		// downscale cannot step by more than 2 in 8-bit output.
		snprintf (Msg, sizeof Msg, "%u -> %u, largest step is %u (<= 2)",
			  nSrcW, nDstW, nMaxStep);
		Expect (nMaxStep <= 2, Msg);
	}
}

static void TestSpike (void)
{
	printf ("pico de un pixel: se reparte, no desaparece\n");

	// A single bright pixel in a black row, downscaled.  The point of a box
	// filter is that the pixel is *averaged* into its neighbourhood instead
	// of being either kept whole or dropped: with nearest-neighbour it is
	// dropped (invisible thin text strokes) or kept (aliasing, the "dientes").
	const unsigned nSrcW = 640;
	const unsigned nDstW = 466;

	std::vector<u32> Src (nSrcW, 0), Dst (nDstW, 0);

	const unsigned nSpike = 300;
	Src[nSpike] = Rgb (255, 255, 255);

	ResampleRowBox (Src.data (), nSrcW, Dst.data (), nDstW);

	unsigned nLit = 0;
	unsigned nTotal = 0;
	unsigned nPeak = 0;
	for (unsigned i = 0; i < nDstW; i++)
	{
		const unsigned nLevel = (Dst[i] >> 16) & 0xFF;
		if (nLevel != 0)
		{
			nLit++;
		}
		nTotal += nLevel;
		if (nLevel > nPeak)
		{
			nPeak = nLevel;
		}
	}

	char Msg[160];
	snprintf (Msg, sizeof Msg, "the spike lights %u output pixels (not 0, not 1)", nLit);
	Expect (nLit >= 1 && nLit <= 3, Msg);

	snprintf (Msg, sizeof Msg, "and is softened, not full brightness (peak %u of 255)", nPeak);
	Expect (nPeak > 0 && nPeak < 255, Msg);

	// Energy: one source pixel of 255 spread over the destination.  The box
	// filter preserves the mean, so the sum of the output levels must be
	// close to 255 x (nDstW/nSrcW) x (255/255)... in the level scale it is
	// 255 * nDstW/nSrcW, plus or minus rounding on each of a few pixels.
	const unsigned nExpected = 255 * nDstW / nSrcW;
	snprintf (Msg, sizeof Msg, "total energy %u is within 3 of %u", nTotal, nExpected);
	Expect (nTotal + 3 >= nExpected && nTotal <= nExpected + 3, Msg);
}

static void TestIdentity (void)
{
	printf ("1:1 es la fila tal cual\n");

	const unsigned nW = 97;		// deliberately not a power of two
	std::vector<u32> Src (nW), Dst (nW);

	unsigned nSeed = 12345;
	for (unsigned i = 0; i < nW; i++)
	{
		nSeed = nSeed * 1103515245u + 12345u;
		Src[i] = nSeed & 0x00FFFFFF;
	}

	ResampleRowBox (Src.data (), nW, Dst.data (), nW);

	bool bSame = true;
	for (unsigned i = 0; i < nW; i++)
	{
		// The packed multiply-shift rounds down by at most one level per
		// channel, so "unchanged" means "within one level", not "bit equal".
		const u32 a = Src[i], b = Dst[i];
		for (unsigned nShift : { 16u, 8u, 0u })
		{
			const int na = static_cast<int> ((a >> nShift) & 0xFF);
			const int nb = static_cast<int> ((b >> nShift) & 0xFF);
			if (na - nb > 1 || nb - na > 1)
			{
				bSame = false;
			}
		}
	}

	Expect (bSame, "1:1 keeps every pixel (within one level of rounding)");
}

int main (void)
{
	TestFlat ();
	TestRamp ();
	TestSpike ();
	TestIdentity ();

	printf ("\n");
	if (s_nFailures != 0)
	{
		printf ("%u fallos\n", s_nFailures);
		return 1;
	}

	printf ("0 fallos\n");
	return 0;
}
